import numpy as np
import time
from scipy.optimize import minimize


def _R(h):
    h = np.asarray(h, dtype=float)
    if h.size == 0 or not np.all(np.isfinite(h)) or h.max() <= 0:
        return -1.0
    h = np.maximum(h, 0.0)
    s = h.sum()
    if s <= 0:
        return -1.0
    L = np.concatenate(([0.0], np.convolve(h, h), [0.0]))
    l2 = np.sum(L[:-1] ** 2 + L[:-1] * L[1:] + L[1:] ** 2) / 3.0
    linf = L.max()
    if linf <= 0:
        return -1.0
    return l2 / (s * s * linf)


def _optimize_shape(h0, deadline, use_powell=True):
    """Directly optimize heights (not logs), fixing scale by normalization.
    Works well for small N where the optimum is near a known shape."""
    N = h0.size
    if N < 2:
        return h0, _R(h0)

    # parametrize: first entry 1, rest free >=0 via softplus-ish clip
    def unpack(x):
        h = np.empty(N)
        h[0] = 1.0
        h[1:] = np.maximum(x, 0.0)
        return h

    def negR(x):
        return -_R(unpack(x))

    x0 = np.maximum(h0[1:] / (h0[0] if h0[0] > 0 else 1.0), 1e-9)
    best_h = h0.copy()
    best_R = _R(h0)
    try:
        res = minimize(negR, x0, method='Powell',
                       options={'maxiter': 20000, 'xtol': 1e-10, 'ftol': 1e-13})
        h = unpack(res.x)
        r = _R(h)
        if r > best_R:
            best_R = r
            best_h = h
    except Exception:
        pass
    return best_h, best_R


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.82

    best_h = None
    best_R = -1.0

    if start is not None:
        hs = np.asarray(start, dtype=float)
        if hs.size > 0 and np.all(np.isfinite(hs)) and hs.max() > 0:
            r = _R(hs)
            if r > best_R:
                best_R = r
                best_h = hs.copy()

    # Seed the search with the sharp peak shape known to be near-optimal
    # for small N. The optimum for small N tends to be a "tent"/spike.
    rng = np.random.default_rng(20240607)

    def _seed_tent(N):
        # triangular spike centered
        i = np.arange(N)
        c = (N - 1) / 2.0
        h = np.maximum(1.0 - np.abs(i - c) / (c + 1e-9), 0.05)
        return h

    def _seed_geom(N, ratio=0.5):
        h = ratio ** np.arange(N)
        return h

    def _seed_flat(N):
        return np.ones(N)

    candidates = []
    # Try many small N with several seeds, since small N give the highest R.
    for N in range(2, 41):
        candidates.append((N, _seed_tent(N)))
        candidates.append((N, _seed_geom(N, 0.5)))
        candidates.append((N, _seed_geom(N, 0.7)))
        candidates.append((N, _seed_flat(N)))
    # Add the start's own N (in case it's larger and already good)
    if best_h is not None:
        candidates.append((best_h.size, best_h.copy()))

    # Phase 1: fast direct optimization on each candidate seed
    for (N, seed) in candidates:
        if time.process_time() > deadline:
            break
        h, r = _optimize_shape(seed, deadline)
        if r > best_R:
            best_R = r
            best_h = h.copy()

    # Phase 2: refine the best solution with more local polishing
    if best_h is not None:
        while time.process_time() < deadline:
            h, r = _optimize_shape(best_h, deadline)
            if r > best_R + 1e-12:
                best_R = r
                best_h = h.copy()
            else:
                break

    # Phase 3: try tiny perturbations of the best solution (basin escape)
    if best_h is not None:
        base = best_h.copy()
        for trial in range(200):
            if time.process_time() > deadline:
                break
            h = base.copy()
            # perturb a few entries
            k = rng.integers(1, max(2, h.size // 2 + 1))
            idx = rng.choice(h.size, size=min(k, h.size), replace=False)
            h[idx] *= np.exp(rng.normal(0, 0.15, size=idx.size))
            h = np.maximum(h, 0.0)
            h, r = _optimize_shape(h, deadline)
            if r > best_R:
                best_R = r
                best_h = h.copy()
                base = best_h.copy()

    if best_h is None:
        best_h = _seed_tent(7)
    return np.asarray(best_h, dtype=float)

import numpy as np
import time
from scipy.optimize import minimize


def _R(h):
    h = np.asarray(h, dtype=float)
    if h.size == 0 or not np.all(np.isfinite(h)) or h.max() <= 0:
        return -1.0
    h = np.maximum(h, 0.0)
    s = h.sum()
    if s <= 0:
        return -1.0
    L = np.concatenate(([0.0], np.convolve(h, h), [0.0]))
    l2 = np.sum(L[:-1] ** 2 + L[:-1] * L[1:] + L[1:] ** 2) / 3.0
    linf = L.max()
    if linf <= 0:
        return -1.0
    return l2 / (s * s * linf)


def _R_grad_free_ops(h):
    """Return (R, L, peak_index)."""
    h = np.maximum(np.asarray(h, dtype=float), 0.0)
    s = h.sum()
    L = np.convolve(h, h)
    m = L.max()
    L2 = np.sum(L[:-1] ** 2 + L[:-1] * L[1:] + L[1:] ** 2) / 3.0
    return L2 / (s * s * m), L, int(np.argmax(L))


def _smooth(h, k=1):
    if k <= 0 or h.size < 2 * k + 1:
        return h
    ker = np.ones(2 * k + 1)
    out = np.convolve(h, ker, mode='same')
    edge = np.convolve(np.ones_like(h), ker, mode='same')
    return out / edge


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.80

    def left():
        return time.process_time() < deadline

    best_h = None
    best_R = -1.0

    if start is not None:
        hs = np.asarray(start, dtype=float)
        if hs.size > 0 and np.all(np.isfinite(hs)) and hs.max() > 0:
            r = _R(hs)
            if r > best_R:
                best_R = r
                best_h = hs.copy()

    rng = np.random.default_rng(1234567)

    def make_full(x, N):
        h = np.empty(N)
        h[0] = 1.0
        h[1:] = np.exp(np.clip(x, -20.0, 20.0))
        return h

    def negR(x, N):
        return -_R(make_full(x, N))

    def try_accept(h):
        nonlocal best_h, best_R
        h = np.maximum(np.asarray(h, dtype=float), 0.0)
        r = _R(h)
        if r > best_R:
            best_R = r
            best_h = h.copy()
            return True
        return False

    # ---- 1. Local polish of the start with Nelder-Mead on log heights ----
    if best_h is not None and best_h.size >= 2 and left():
        h0 = np.maximum(best_h, 1e-12)
        x0 = np.log(h0[1:] / h0[0])
        try:
            res = minimize(negR, x0, args=(best_h.size,), method='Nelder-Mead',
                           options={'maxiter': 6000, 'xatol': 1e-10, 'fatol': 1e-13})
            try_accept(make_full(res.x, best_h.size))
        except Exception:
            pass

    # ---- 2. Resample start to nearby sizes & polish ----
    if best_h is not None and left():
        N0 = best_h.size
        for N in (max(2, N0 - 2), N0 + 1, N0 + 2, N0 + 4):
            if not left():
                break
            # resample using np.interp on cumulative mass (better than linear)
            c = np.cumsum(np.maximum(best_h, 0.0))
            c /= c[-1]
            xs = np.linspace(0, 1, N + 1)
            targets = np.linspace(0, 1, N0 + 1)
            hs = np.interp(xs, targets, np.concatenate(([0.0], best_h)))
            hs = np.maximum(hs, 1e-12)
            x0 = np.log(hs[1:] / hs[0])
            try:
                res = minimize(negR, x0, args=(N,), method='Nelder-Mead',
                               options={'maxiter': 4000, 'xatol': 1e-10, 'fatol': 1e-13})
                try_accept(make_full(res.x, N))
            except Exception:
                pass

    # ---- 3. Multi-start small-N search ----
    Ns = [2, 3, 4, 5, 6, 7, 8, 10, 12, 14, 18, 22, 28, 36, 48, 64, 90]
    if best_h is not None:
        Ns.append(best_h.size)

    for N in Ns:
        if not left():
            break
        starts = []
        # geometric decay
        starts.append(np.log(0.5 ** np.arange(1, N)) if N > 1 else np.array([]))
        # linear ramp
        lin = np.clip(np.array([(N - i) / N for i in range(1, N)]), 1e-6, None)
        starts.append(np.log(lin))
        # constant
        starts.append(np.zeros(max(N - 1, 0)))
        # random
        for _ in range(6):
            starts.append(rng.uniform(-5.0, 0.0, size=max(N - 1, 0)))

        for x0 in starts:
            if not left():
                break
            if x0.size == 0:
                try_accept(make_full(x0, N))
                continue
            try:
                res = minimize(negR, x0, args=(N,), method='Nelder-Mead',
                               options={'maxiter': 3000, 'xatol': 1e-9, 'fatol': 1e-12})
                try_accept(make_full(res.x, N))
            except Exception:
                pass

    # ---- 4. Local coordinate / pattern search on best_h (in log space) ----
    if best_h is not None and best_h.size >= 2 and left():
        h = np.maximum(best_h.copy(), 1e-12)
        # normalize scale
        h = h / h[0]
        x = np.log(h[1:])
        N = h.size
        cur = _R(np.concatenate(([1.0], np.exp(x))))
        step = 0.5
        while step > 1e-4 and left():
            improved = False
            for i in range(x.size):
                if not left():
                    break
                for sgn in (+1.0, -1.0):
                    xn = x.copy()
                    xn[i] += sgn * step
                    rn = _R(np.concatenate(([1.0], np.exp(np.clip(xn, -30, 30)))))
                    if rn > cur + 1e-12:
                        cur = rn
                        x = xn
                        improved = True
                        break
            if not improved:
                step *= 0.5
        try_accept(np.concatenate(([1.0], np.exp(np.clip(x, -30, 30)))))

    # ---- 5. Smoothing attempts ----
    if best_h is not None and best_h.size >= 3:
        for k in (1, 2, 3):
            if not left():
                break
            try_accept(_smooth(best_h, k))

    if best_h is None:
        best_h = np.ones(50)
    return np.asarray(best_h, dtype=float)

