    L = np.empty(conv.size + 2)
    L[0] = 0.0
    L[1:-1] = conv
    L[-1] = 0.0
    m = L.max()
    if m <= 0:
        return 0.0
    L2 = (L[:-1] ** 2 + L[:-1] * L[1:] + L[1:] ** 2).sum() / 3.0
    return L2 / (s * s * m)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    N = 50000
    n = np.arange(1, N + 1, dtype=float)          # n+1 for n=0..N-1
    m = np.arange(N, 0, -1, dtype=float)          # N-n for n=0..N-1
    logn = np.log(n)
    logm = np.log(m)

    def make(alpha, beta):
        return np.exp(alpha * logn + beta * logm)

    best_R = -1.0
    best_ab = (-0.5, 0.0)

    # Coarse grid search
    alphas = np.arange(-0.8, -0.2 + 1e-9, 0.05)
