import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _R_from_L(L, s):
    m = L.max()
    if m <= 0 or s <= 0:
        return 0.0
    L2 = (L[:-1] ** 2 + L[:-1] * L[1:] + L[1:] ** 2).sum() / 3.0
    return L2 / (s * s * m)


def _R_fast(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    conv = fftconvolve(h, h)
    L = np.empty(conv.size + 2)
    L[0] = 0.0
    L[1:-1] = conv
    L[-1] = 0.0
    return _R_from_L(L, s)


def _binom(N):
    h = np.empty(N, dtype=float)
    h[0] = 1.0
    for n in range(N - 1):
        h[n + 1] = h[n] * (2.0 * n + 1.0) / (2.0 * n + 2.0)
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    N = 50000
    base = _binom(N)
    base = base / base.max()

    n = np.arange(N, dtype=float)
    x = 2.0 * n / (N - 1) - 1.0
    K = 10
    T = np.empty((K, N))
    T[0] = np.ones(N)
    if K > 1:
        T[1] = x
    for k in range(2, K):
        T[k] = 2.0 * x * T[k - 1] - T[k - 2]

    best_h = base.copy()
    best_r = _R_fast(best_h)

    if start is not None:
        hs = np.asarray(start, dtype=float)
        if hs.size > 0 and hs.sum() > 0 and hs.size <= 50000:
            rs = _R_fast(hs)
            if rs > best_r:
                best_r = rs
                best_h = hs.copy()

    def make_h(a):
        logp = a @ T
        logp = np.clip(logp, -50.0, 50.0)
        return base * np.exp(logp)

    def negR(a):
        if time.process_time() > deadline:
            return 1.0
        return -_R_fast(make_h(a))

    # seed with start: fit start onto base*exp(T^T a) approximately via log-ratio
    a0 = np.zeros(K)
    if start is not None:
        hs = np.asarray(start, dtype=float)
        if hs.size == N and hs.sum() > 0:
            ratio = np.log(np.clip(hs / base, 1e-12, None))
            # least squares fit of T^T a ~ ratio
            try:
                a_fit, *_ = np.linalg.lstsq(T.T, ratio, rcond=None)
                if np.all(np.isfinite(a_fit)):
                    a0 = a_fit
            except Exception:
                pass

    best_a = a0.copy()
    best_val = -_R_fast(make_h(a0))
    if -best_val > best_r:
        best_r = -best_val
