import time
from scipy.signal import fftconvolve
from scipy.optimize import minimize


def _R_from_L(L, s):
    m = L.max()
    if m <= 0 or s <= 0:
        return 0.0
    L2 = (L[:-1] ** 2 + L[:-1] * L[1:] + L[1:] ** 2).sum() / 3.0
    return L2 / (s * s * m)


def _R_fast(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    conv = fftconvolve(h, h)
    L = np.empty(conv.size + 2)
    L[0] = 0.0
    L[1:-1] = conv
    L[-1] = 0.0
    return _R_from_L(L, s)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85
    N = 50000

    # Family: h_k = a * C(1/2,k) * q^k convolved with binomial b, like p0041
    b = np.empty(N, dtype=float)
    b[0] = 1.0
    for n in range(N - 1):
        b[n + 1] = b[n] * (2.0 * n + 1.0) / (2.0 * n + 2.0)

    def _build(a):
        q = (1.0 - a * a) / (a * a)
        c = np.empty(N, dtype=float)
        c[0] = a
        for k in range(1, N):
            c[k] = c[k - 1] * ((0.5 - (k - 1)) / k) * q
        h = fftconvolve(c, b)[:N]
        return np.maximum(h, 0.0)

    best_h = None
    best_r = -1.0

    if start is not None:
        hs = np.asarray(start, dtype=float)
        if hs.size > 0 and hs.sum() > 0 and hs.size <= 50000:
            rs = _R_fast(hs)
            if rs > best_r:
                best_r = rs
                best_h = hs.copy()

    # Coarse grid over a
    grid = np.linspace(0.55, 0.99, 23)
    best_a = 0.9
    for a in grid:
        if time.process_time() > deadline:
            break
        h = _build(a)
        r = _R_fast(h)
        if r > best_r:
            best_r = r
            best_h = h
            best_a = a

    # Golden-section refine around best a
    lo = max(0.5, best_a - 0.05)
    hi = min(1.0, best_a + 0.05)
    gr = (np.sqrt(5.0) - 1.0) / 2.0
    c1 = hi - gr * (hi - lo)
    c2 = lo + gr * (hi - lo)
    h1 = _build(c1); r1 = _R_fast(h1)
    h2 = _build(c2); r2 = _R_fast(h2)
    for _ in range(40):
        if time.process_time() > deadline:
            break
        if r1 > r2:
            hi, c2, r2, h2 = c2, c1, r1, h1
            c1 = hi - gr * (hi - lo)
            h1 = _build(c1); r1 = _R_fast(h1)
        else:
            lo, c1, r1, h1 = c1, c2, r2, h2
            c2 = lo + gr * (hi - lo)
            h2 = _build(c2); r2 = _R_fast(h2)
    if r1 > best_r:
        best_r, best_h = r1, h1
    if r2 > best_r:
        best_r, best_h = r2, h2

    # Local polish on c (free coefficients via a few Nelder-Mead steps on a)
    if time.process_time() < deadline and best_h is not None:
        def negR_a(a_arr):
            if time.process_time() > deadline:
                return 1.0
            a = float(np.clip(a_arr[0], 0.3, 1.0))
            return -_R_fast(_build(a))
        try:
            res = minimize(negR_a, np.array([best_a]), method='Nelder-Mead',
                           options={'maxiter': 60, 'xatol': 1e-7, 'fatol': 1e-12})
            a_val = float(np.clip(res.x[0], 0.3, 1.0))
            h = _build(a_val)
            r = _R_fast(h)
            if r > best_r:
                best_r, best_h = r, h
        except Exception:
            pass

    print(f"best R = {best_r:.9f}")
    if best_h is None:
        best_h = b / b.max()
    return best_h

