def _R_from_conv(conv, s):
    if s <= 0:
        return 0.0
    m = conv.max()
    if m <= 0:
        return 0.0
    L = conv
    L2 = (L[:-1] ** 2 + L[:-1] * L[1:] + L[1:] ** 2).sum() / 3.0
    L2 += (L[0] ** 2 + L[-1] ** 2) / 3.0
    return L2 / (s * s * m)


def _R_fast(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    n = h.size
    nfft = 1
    while nfft < 2 * n - 1:
        nfft <<= 1
    H = np.fft.rfft(h, nfft)
    conv = np.fft.irfft(H * H, nfft)[:2 * n - 1]
    return _R_from_conv(conv, s)


def _binom(N):
    h = np.empty(N, dtype=float)
    h[0] = 1.0
    for n in range(N - 1):
        h[n + 1] = h[n] * (2.0 * n + 1.0) / (2.0 * n + 2.0)
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.82

    N = 50000
    base = _binom(N)
    base = base / base.max()

    best_h = base.copy()
    best_r = _R_fast(best_h)

    if start is not None:
        hs = np.asarray(start, dtype=float)
        if hs.size > 0 and hs.sum() > 0 and hs.size <= 50000:
            rs = _R_fast(hs)
            if rs > best_r:
                best_r = rs
                best_h = hs.copy()

    # Work in log-space on top of binomial base.
    # Parameterization: log h = log base + sum_k a_k * T_k(x)
    n = np.arange(N, dtype=float)
    x = 2.0 * n / (N - 1) - 1.0
    K = 12
    T = np.empty((K, N))
    T[0] = np.ones(N)
    if K > 1:
        T[1] = x
    for k in range(2, K):
        T[k] = 2.0 * x * T[k - 1] - T[k - 2]

    def make_h(a):
        logp = a @ T
        logp = np.clip(logp, -30.0, 30.0)
        return base * np.exp(logp)

    a0 = np.zeros(K)
    if start is not None:
        hs = np.asarray(start, dtype=float)
        if hs.size == N and hs.sum() > 0:
            ratio = np.log(np.clip(hs / base, 1e-15, None))
            try:
                a_fit, *_ = np.linalg.lstsq(T.T, ratio, rcond=None)
                if np.all(np.isfinite(a_fit)):
                    a0 = a_fit
            except Exception:
                pass

    # Check a0
    h_a0 = make_h(a0)
    r_a0 = _R_fast(h_a0)
    if r_a0 > best_r:
        best_r = r_a0
        best_h = h_a0
        best_a = a0.copy()
    else:
        best_a = np.zeros(K)

    def negR(a):
        if time.process_time() > deadline:
            return 1.0
        return -_R_fast(make_h(a))

    rng = np.random.default_rng(2024)

    def run_nm(a_start, maxiter):
        try:
            res = minimize(negR, a_start, method='Nelder-Mead',
                           options={'maxiter': maxiter, 'xatol': 1e-8,
                                    'fatol': 1e-12, 'adaptive': True})
            return res.x, -res.fun
        except Exception:
            return a_start, -1.0

