    ax, val = run_nm(best_a, 1500)
    if val > best_r:
        best_r = val
        best_a = ax
        best_h = make_h(ax)

    # Restarts with perturbed starting points
    restart = 0
    while time.process_time() < deadline and restart < 60:
        restart += 1
        scale = 0.005 * (1.0 + restart * 0.15)
        a_start = best_a + rng.normal(0, scale, K)
        ax, val = run_nm(a_start, 400)
        if val > best_r:
            best_r = val
            best_a = ax
            best_h = make_h(ax)

    # Final check
    r_final = _R_fast(best_h)
    if r_final > best_r:
        best_r = r_final

    print(f"best R = {best_r:.9f}, restarts = {restart}")
