    if best_c_val > best_r:
        best_r = best_c_val
        best_h = make_h_add(best_c)

    step = 0.02 * cscale
    c_cur = best_c.copy()
    cur_val = best_c_val
    it = 0
    while time.process_time() < deadline and it < 200000:
        it += 1
        i = rng.integers(0, M)
        old = c_cur[i]
        delta = step * rng.normal()
        newv = old + delta
        if newv < 0:
            newv = 0.0
        c_cur[i] = newv
        v = _R_fast(make_h_add(c_cur))
        if v >= cur_val:
            cur_val = v
        else:
            c_cur[i] = old
        if it % 2000 == 0:
            if cur_val > best_c_val:
                best_c_val = cur_val
                best_c = c_cur.copy()
                if cur_val > best_r:
                    best_r = cur_val
                    best_h = make_h_add(best_c)
            step *= 0.85
            if step < 1e-6 * cscale:
                step = 0.02 * cscale
