        best_c_val = cur_val
        best_c = c_cur.copy()
    if best_c_val > best_r:
        h_final = make_h_add(best_c)
        r_final = _R_fast(h_final)
        if r_final > best_r:
            best_h = h_final
            best_r = r_final

    # --- Tail coordinate descent (experiment) ---
    tail_deadline = t0 + min(budget_seconds * 0.93, 28.0)
    h = best_h.copy()
    if h.size == N:
        cur_r = _R_fast(h)
        if cur_r > best_r:
            best_r = cur_r
        tail_start = 45000
        sigmas = [1e-3, 3e-4, 1e-4, 3e-5]
        evals = 0
        si = 0
        tail_rng = np.random.default_rng(1234567)
        while time.process_time() < tail_deadline:
            evals += 1
            sigma = sigmas[si % len(sigmas)]
            if evals % 5000 == 0:
                si += 1
                # block scaling of 100 contiguous tail entries
                b0 = tail_rng.integers(tail_start, N - 100)
                old_block = h[b0:b0 + 100].copy()
                delta = sigma * tail_rng.normal()
                h[b0:b0 + 100] *= np.exp(delta)
                v = _R_fast(h)
                if v >= cur_r:
                    cur_r = v
                    if v > best_r:
                        best_r = v
                        best_h = h.copy()
                else:
                    h[b0:b0 + 100] = old_block
            else:
                i = tail_rng.integers(tail_start, N)
                old = h[i]
                delta = sigma * tail_rng.normal()
                h[i] = old * np.exp(delta)
                v = _R_fast(h)
                if v >= cur_r:
                    cur_r = v
                    if v > best_r:
                        best_r = v
                        best_h = h.copy()
                else:
                    h[i] = old

    print(f"best R = {best_r:.9f}, restarts = {restart}, local iters = {it}")
    return best_h

