        if hs.size > 0 and hs.sum() > 0 and hs.size <= 50000:
            rs = _R_fast(hs)
            if np.isfinite(rs) and rs > best_r:
                best_r = rs
                best_h = hs.copy()

    n = np.arange(N, dtype=float)
    x = 2.0 * n / (N - 1) - 1.0

