    for k in range(N - 1):
        base[k + 1] = base[k] * (2.0 * k + 1.0) / (2.0 * k + 2.0)
    base /= base.max()

    # Chebyshev basis for log-perturbation
    K = 24
    T = np.empty((K, N))
    T[0] = 1.0
    if K > 1:
        T[1] = x
    for k in range(2, K):
        T[k] = 2.0 * x * T[k - 1] - T[k - 2]

    a0 = np.zeros(K)
    if best_h is not None and best_h.size == N:
        ratio = np.log(np.clip(best_h / base, 1e-12, None))
        try:
            a_fit, *_ = np.linalg.lstsq(T.T, ratio, rcond=None)
            if np.all(np.isfinite(a_fit)):
                a0 = a_fit
        except Exception:
