import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _R_from_conv(conv, s):
    if s <= 0:
        return 0.0
    m = conv.max()
    if m <= 0:
        return 0.0
    L2 = (conv[:-1] ** 2 + conv[:-1] * conv[1:] + conv[1:] ** 2).sum() / 3.0
    L2 += (conv[0] ** 2 + conv[-1] ** 2) / 3.0
    return L2 / (s * s * m)


def _R_from_L(L, s):
    m = L.max()
    if m <= 0 or s <= 0:
        return 0.0
    L2 = (L[:-1] ** 2 + L[:-1] * L[1:] + L[1:] ** 2).sum() / 3.0
    return L2 / (s * s * m)


def _R_fast(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    conv = fftconvolve(h, h)
    return _R_from_conv(conv, s)


def _binom(N):
    h = np.empty(N, dtype=float)
    h[0] = 1.0
    for n in range(N - 1):
        h[n + 1] = h[n] * (2.0 * n + 1.0) / (2.0 * n + 2.0)
    return h / h.max()


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.82

    N = 50000

    best_h = None
    best_r = -1.0
    if start is not None:
        hs = np.asarray(start, dtype=float)
        if hs.size > 0 and hs.sum() > 0 and hs.size <= 50000:
            rs = _R_fast(hs)
            if np.isfinite(rs) and rs > best_r:
                best_r = rs
                best_h = hs.copy()

    # Coarse profile optimization: represent h via its cumulative distribution shape.
    # Use M control points (heights) uniformly spaced; interpolate to fine grid.
    # The optimal profile is a smooth symmetric bump. Parameterize by half-profile
    # with M points and mirror.
    M = 60  # half-profile control points

    # Base shape: binomial at coarse resolution
    base_coarse = _binom(2 * M - 1)

    # Fine grid mapping
    xc = np.linspace(-1.0, 1.0, 2 * M - 1)
    xf = np.linspace(-1.0, 1.0, N)

    def interp_to_fine(coarse):
        # piecewise linear interpolation on symmetric grid
        return np.interp(xf, xc, coarse)

    def make_h_from_coarse(c, base):
        # multiplicative perturbation in log space then interp
        logp = np.clip(c, -30.0, 30.0)
        coarse = base * np.exp(logp)
        h = interp_to_fine(coarse)
        h = np.clip(h, 0.0, None)
        return h

    def negR_coarse(c, base):
        if time.process_time() > deadline:
            return 1.0
        return -_R_fast(make_h_from_coarse(c, base))

    # Initialize from start if available
    c0 = np.zeros(2 * M - 1)
    if best_h is not None and best_h.size == N:
        # sample start onto coarse grid
        hc = np.interp(xc, xf, best_h)
        ratio = np.log(np.clip(hc / base_coarse, 1e-12, None))
        if np.all(np.isfinite(ratio)):
            c0 = ratio

    best_c = c0.copy()
    val0 = _R_fast(make_h_from_coarse(c0, base_coarse))
    if val0 > best_r:
        best_r = val0
        best_h = make_h_from_coarse(c0, base_coarse)

    # Optimize coarse profile with L-BFGS-B (smooth-ish objective)
    def run_opt(c_start, maxiter=500):
        try:
            res = minimize(negR_coarse, c_start, args=(base_coarse,),
                           method='Nelder-Mead',
                           options={'maxiter': maxiter, 'xatol': 1e-7, 'fatol': 1e-12})
            return res.x, -res.fun
        except Exception:
            return c_start, -1.0

    # Try L-BFGS-B first (faster for smooth objective)
    def run_lbfgs(c_start, maxiter=200):
        try:
            res = minimize(negR_coarse, c_start, args=(base_coarse,),
                           method='L-BFGS-B',
                           options={'maxiter': maxiter, 'ftol': 1e-15, 'gtol': 1e-10})
            return res.x, -res.fun
        except Exception:
            return c_start, -1.0

    if time.process_time() < deadline:
        cx, val = run_lbfgs(best_c, 300)
        if val > best_r:
            best_r, best_c = val, cx
            best_h = make_h_from_coarse(cx, base_coarse)

    if time.process_time() < deadline:
        cx, val = run_opt(best_c, 3000)
        if val > best_r:
            best_r, best_c = val, cx
            best_h = make_h_from_coarse(cx, base_coarse)

    rng = np.random.default_rng(987654321)
    restart = 0
    while time.process_time() < deadline * 0.85 and restart < 20:
        restart += 1
        scale = 0.01 * (1.0 + restart * 0.2)
        c_start = best_c + rng.normal(0, scale, best_c.size)
        cx, val = run_opt(c_start, 1500)
        if val > best_r:
            best_r, best_c = val, cx
            best_h = make_h_from_coarse(cx, base_coarse)

    # Refine at finer resolution near the found shape
    if time.process_time() < deadline:
        h_ref = best_h.copy()
        # local fine optimization: use log perturbation on full grid but coarse
        # Use piecewise-constant segments of 500 with linear interp
        seg = 100
        nseg = N // seg
        xs = np.linspace(0, N - 1, nseg).astype(int)
        hs_coarse = np.array([h_ref[xs[i]] for i in range(nseg)])
        # endpoints
        xs = np.concatenate([[0], xs, [N - 1]])
        hs_coarse = np.concatenate([[h_ref[0]], hs_coarse, [h_ref[-1]]])

        base2 = np.maximum(hs_coarse, 1e-12)

        def make_h2(c):
            logp = np.clip(c, -30.0, 30.0)
            coarse = base2 * np.exp(logp)
            h = np.interp(np.arange(N), xs, coarse)
            return np.clip(h, 0.0, None)

        def negR2(c):
            if time.process_time() > deadline:
                return 1.0
            return -_R_fast(make_h2(c))

        c2 = np.zeros(xs.size)
        if time.process_time() < deadline:
            try:
                res = minimize(negR2, c2, method='Nelder-Mead',
                               options={'maxiter': 4000, 'xatol': 1e-8, 'fatol': 1e-13})
                if -res.fun > best_r:
                    h2 = make_h2(res.x)
                    r2 = _R_fast(h2)
                    if r2 > best_r:
                        best_r = r2
                        best_h = h2
            except Exception:
                pass

    # Final: try direct fine-grid local search around best_h using multiplicative
    # perturbation with a few random basis functions
    if time.process_time() < deadline:
        hh = best_h.copy()
        r_now = _R_fast(hh)
        n_pert = 8
        for it in range(30):
            if time.process_time() > deadline:
                break
            # random smooth perturbation
            t = np.linspace(0, np.pi, N)
            pert = np.zeros(N)
            for k in range(n_pert):
                freq = (k + 1) * rng.uniform(0.5, 3.0)
                amp = rng.normal(0, 0.002 * (1.0 + 0.3 * k))
                pert += amp * np.sin(freq * t) * (r_now * 0.0 + 1.0)
            cand = np.clip(hh * np.exp(pert), 0.0, None)
            rc = _R_fast(cand)
            if rc > r_now:
                r_now = rc
                hh = cand
                if rc > best_r:
                    best_r = rc
                    best_h = cand

    if best_h is None:
        best_h = _binom(N)
        best_r = _R_fast(best_h)

    print(f"best R = {best_r:.9f}, restarts = {restart}")
    return best_h

