def _R_fast(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    conv = fftconvolve(h, h)
    return _R_from_conv(conv, s)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.80

    N = 50000
    best_h = None
    best_r = -1.0
    if start is not None:
        hs = np.asarray(start, dtype=float)
        if hs.size > 0 and hs.sum() > 0 and hs.size <= 50000:
            rs = _R_fast(hs)
            if np.isfinite(rs) and rs > best_r:
                best_r = rs
                best_h = hs.copy()

    n = np.arange(N, dtype=float)
    x = 2.0 * n / (N - 1) - 1.0

    # base: binomial-like profile (near-optimal shape)
    base = np.empty(N, dtype=float)
    base[0] = 1.0
    for k in range(N - 1):
        base[k + 1] = base[k] * (2.0 * k + 1.0) / (2.0 * k + 2.0)
    base /= base.max()

    # Chebyshev basis for log-perturbation
    K = 24
    T = np.empty((K, N))
    T[0] = 1.0
    if K > 1:
        T[1] = x
    for k in range(2, K):
        T[k] = 2.0 * x * T[k - 1] - T[k - 2]

    a0 = np.zeros(K)
    if best_h is not None and best_h.size == N:
        ratio = np.log(np.clip(best_h / base, 1e-12, None))
        try:
            a_fit, *_ = np.linalg.lstsq(T.T, ratio, rcond=None)
            if np.all(np.isfinite(a_fit)):
                a0 = a_fit
        except Exception:
            pass

    def make_h(a):
        logp = np.clip(a @ T, -50.0, 50.0)
        return base * np.exp(logp)

