    val0 = _R_fast(make_h(a0))
    if val0 > best_r:
        best_r = val0
        best_h = make_h(a0)

    rng = np.random.default_rng(424242)

    def run_nm(a_start, maxiter, fatol=1e-13, xatol=1e-10):
        try:
            res = minimize(negR, a_start, method='Nelder-Mead',
                           options={'maxiter': maxiter, 'xatol': xatol, 'fatol': fatol})
            return res.x, -res.fun
        except Exception:
            return a_start, -1.0

    ax, val = run_nm(best_a, 4000)
    if val > best_r:
        best_r, best_a = val, ax
        best_h = make_h(ax)

    restart = 0
    while time.process_time() < deadline * 0.7 and restart < 60:
        restart += 1
        scale = 0.003 * (1.0 + restart * 0.15)
        a_start = best_a + rng.normal(0, scale, K)
        ax, val = run_nm(a_start, 1500)
        if val > best_r:
            best_r, best_a = val, ax
            best_h = make_h(ax)
        if time.process_time() > deadline * 0.7:
            break

    if time.process_time() < deadline:
        ax, val = run_nm(best_a, 4000)
        if val > best_r:
            best_r, best_a = val, ax
            best_h = make_h(ax)

    h_final = make_h(best_a)
    r_final = _R_fast(h_final)
    if r_final > best_r:
        best_h, best_r = h_final, r_final

    print(f"best R = {best_r:.9f}, restarts = {restart}")
    return best_h

