    L[-1] = 0.0
    return _R_from_L(L, s)


def _binom(N):
    h = np.empty(N, dtype=float)
    h[0] = 1.0
    for n in range(N - 1):
        h[n + 1] = h[n] * (2.0 * n + 1.0) / (2.0 * n + 2.0)
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    N = 50000
    base = _binom(N)
    base = base / base.max()

    n = np.arange(N, dtype=float)
    x = 2.0 * n / (N - 1) - 1.0

    # Chebyshev basis for multiplicative (log) perturbation
    K = 20
    T = np.empty((K, N))
    T[0] = np.ones(N)
    if K > 1:
        T[1] = x
    for k in range(2, K):
        T[k] = 2.0 * x * T[k - 1] - T[k - 2]

    best_h = base.copy()
    best_r = _R_fast(best_h)

    a0 = np.zeros(K)
    if start is not None:
        hs = np.asarray(start, dtype=float)
        if hs.size > 0 and hs.sum() > 0 and hs.size <= 50000:
            rs = _R_fast(hs)
            if rs > best_r:
                best_r = rs
                best_h = hs.copy()
            if hs.size == N:
                ratio = np.log(np.clip(hs / base, 1e-12, None))
                try:
                    a_fit, *_ = np.linalg.lstsq(T.T, ratio, rcond=None)
                    if np.all(np.isfinite(a_fit)):
                        a0 = a_fit
                except Exception:
                    pass

    def make_h(a):
        logp = a @ T
        logp = np.clip(logp, -50.0, 50.0)
        return base * np.exp(logp)

    def negR(a):
        if time.process_time() > deadline:
            return 1.0
        return -_R_fast(make_h(a))

    best_a = a0.copy()
    val0 = _R_fast(make_h(a0))
    best_val = val0
    if val0 > best_r:
        best_r = val0
        best_h = make_h(a0)

    rng = np.random.default_rng(20240607)

    def run_nm(a_start, maxiter, fatol=1e-12):
        try:
            res = minimize(negR, a_start, method='Nelder-Mead',
                           options={'maxiter': maxiter, 'xatol': 1e-9, 'fatol': fatol})
            return res.x, -res.fun
        except Exception:
            return a_start, -1.0

    ax, val = run_nm(best_a, 3000)
    if val > best_val:
        best_val, best_a = val, ax
        best_h = make_h(ax)

    restart = 0
    while time.process_time() < deadline * 0.75 and restart < 40:
        restart += 1
        scale = 0.002 * (1.0 + restart * 0.1)
        a_start = best_a + rng.normal(0, scale, K)
        ax, val = run_nm(a_start, 800)
        if val > best_val:
            best_val, best_a = val, ax
            best_h = make_h(ax)
        if time.process_time() > deadline * 0.75:
            break

    # Final targeted polish with a slightly larger basis around the best point
    if time.process_time() < deadline:
        ax, val = run_nm(best_a, 2000)
        if val > best_val:
            best_val, best_a = val, ax
            best_h = make_h(ax)

    h_final = make_h(best_a)
    r_final = _R_fast(h_final)
    if r_final > best_r:
        best_h = h_final
        best_r = r_final

    # ---- Tail-only refinement ----
    if time.process_time() < deadline:
        M = 2000
        J = 12
        if best_h.size == N and M < N:
            hb = best_h.copy()
            tail_base = hb[N - M:].copy()
            if tail_base.sum() > 0 and np.all(tail_base >= 0):
                kk = np.arange(M, dtype=float)
                xt = 2.0 * kk / (M - 1) - 1.0
                Tt = np.empty((J, M))
                Tt[0] = np.ones(M)
                if J > 1:
                    Tt[1] = xt
                for j in range(2, J):
                    Tt[j] = 2.0 * xt * Tt[j - 1] - Tt[j - 2]

                def make_tail(c):
                    logp = c @ Tt
                    logp = np.clip(logp, -50.0, 50.0)
                    h = hb.copy()
                    h[N - M:] = tail_base * np.exp(logp)
                    return h

                def negR_tail(c):
                    if time.process_time() > deadline:
                        return 1.0
                    return -_R_fast(make_tail(c))

                c0 = np.zeros(J)
                try:
                    res = minimize(negR_tail, c0, method='Nelder-Mead',
                                   options={'maxiter': 4000, 'xatol': 1e-10,
                                            'fatol': 1e-13})
                    c_best = res.x
                    h_try = make_tail(c_best)
                    r_try = _R_fast(h_try)
                    if r_try > best_r:
                        best_r = r_try
                        best_h = h_try
                except Exception:
                    pass

    print(f"best R = {best_r:.9f}, restarts = {restart}")
    return best_h

