    L[-1] = 0.0
    return _R_from_L(L, s)


def _binom(N):
    h = np.empty(N, dtype=float)
    h[0] = 1.0
    for n in range(N - 1):
        h[n + 1] = h[n] * (2.0 * n + 1.0) / (2.0 * n + 2.0)
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    N = 50000
    base = _binom(N)
    base = base / base.max()

    n = np.arange(N, dtype=float)
    x = 2.0 * n / (N - 1) - 1.0

    K = 30
    T = np.empty((K, N))
    T[0] = np.ones(N)
    if K > 1:
        T[1] = x
    for k in range(2, K):
        T[k] = 2.0 * x * T[k - 1] - T[k - 2]
    Tb = T[1:]  # k=1..K-1 (K-1 params)

    best_h = base.copy()
    best_r = _R_fast(best_h)

    if start is not None:
        hs = np.asarray(start, dtype=float)
        if hs.size > 0 and hs.sum() > 0 and hs.size <= 50000:
            rs = _R_fast(hs)
            if rs > best_r:
                best_r = rs
                best_h = hs.copy()

    # h_base for the rectangle-fit experiment
    h_base = best_h.copy()
    if h_base.size != N:
        # resample to N if needed
        idx = np.linspace(0, h_base.size - 1, N)
        h_base = np.interp(idx, np.arange(h_base.size), h_base)
    if h_base.max() > 0:
        h_base = h_base / h_base.max()

    knots = np.arange(2 * N + 1, dtype=float)
    denom_j = 2.0 * N

    def make_h(a):
        logp = a @ Tb
        logp = np.clip(logp, -50.0, 50.0)
        return h_base * np.exp(logp)

    def fit_for_w(w):
        q = np.minimum(1.0, np.minimum(knots / w, (denom_j - knots) / w))
        qn = np.sqrt((q * q).sum())
        if qn <= 0:
            return None, -1.0

        def obj(a):
            if time.process_time() > deadline:
                return 1.0
            h = make_h(a)
            conv = fftconvolve(h, h)
            m = conv.max()
            if m <= 0:
                return 1.0
            qq = conv / m
            diff = qq - q
            return (diff * diff).sum() / (qn * qn)

        a0 = np.zeros(K - 1)
        try:
            res = minimize(obj, a0, method='L-BFGS-B',
                           options={'maxiter': 200, 'ftol': 1e-14, 'gtol': 1e-12})
            a = res.x
        except Exception:
            return None, -1.0
        h = make_h(a)
        return h, _R_fast(h)

    for w in (100, 500, 1000, 2000):
        if time.process_time() > deadline:
            break
        h, r = fit_for_w(w)
        if h is not None and r > best_r:
            best_r = r
            best_h = h

    print(f"best R = {best_r:.9f}")
    return best_h

