import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _R_from_L(L, s):
    m = L.max()
    if m <= 0 or s <= 0:
        return 0.0
    L2 = (L[:-1] ** 2 + L[:-1] * L[1:] + L[1:] ** 2).sum() / 3.0
    return L2 / (s * s * m)


def _R_fast(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    conv = fftconvolve(h, h)
    L = np.empty(conv.size + 2)
    L[0] = 0.0
    L[1:-1] = conv
    L[-1] = 0.0
    return _R_from_L(L, s)


def _binom(N):
    h = np.empty(N, dtype=float)
    h[0] = 1.0
    for n in range(N - 1):
        h[n + 1] = h[n] * (2.0 * n + 1.0) / (2.0 * n + 2.0)
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    N = 50000
    base = _binom(N)
    base = base / base.max()

    n = np.arange(N, dtype=float)
    u = n / (N - 1)
    tail = np.clip(1.0 - u, 1e-300, None)
    logtail = np.log(tail)

    best_h = base.copy()
    best_r = _R_fast(best_h)
    best_gamma = 0.0

    if start is not None:
        hs = np.asarray(start, dtype=float)
        if hs.size > 0 and hs.sum() > 0 and hs.size <= 50000:
            rs = _R_fast(hs)
            if rs > best_r:
                best_r = rs
                best_h = hs.copy()

    def make_h(gamma):
        return base * np.exp(-gamma * logtail)

    # Fine grid scan
    gammas = np.arange(0.0, 0.4401, 0.01)
    for g in gammas:
        if time.process_time() > deadline:
            break
        r = _R_fast(make_h(g))
        if r > best_r:
            best_r = r
            best_h = make_h(g)
            best_gamma = g

    # Bounded scalar refine
    if time.process_time() < deadline:
        lo = max(0.0, best_gamma - 0.02)
        hi = best_gamma + 0.02

        def negR(g):
            if time.process_time() > deadline:
                return 1.0
            return -_R_fast(make_h(g))

        try:
            from scipy.optimize import minimize_scalar
            res = minimize_scalar(negR, bounds=(lo, hi), method='bounded',
                                  options={'xatol': 1e-6, 'maxiter': 100})
            g_opt = float(res.x)
            r_opt = -float(res.fun)
            if r_opt > best_r:
                best_r = r_opt
                best_h = make_h(g_opt)
                best_gamma = g_opt
        except Exception:
            pass

    # Direct shape optimisation on a coarse parameterisation, refining around best
    if time.process_time() < deadline:
        K = 20
        x = 2.0 * n / (N - 1) - 1.0
        T = np.empty((K, N))
        T[0] = np.ones(N)
        if K > 1:
            T[1] = x
        for k in range(2, K):
            T[k] = 2.0 * x * T[k - 1] - T[k - 2]
        Tb = T[1:]

        h_base = best_h.copy()
        if h_base.size != N:
            idx = np.linspace(0, h_base.size - 1, N)
            h_base = np.interp(idx, np.arange(h_base.size), h_base)
        if h_base.max() > 0:
            h_base = h_base / h_base.max()

        def make_h2(a):
            logp = a @ Tb
            logp = np.clip(logp, -20.0, 20.0)
            return h_base * np.exp(logp)

        def obj(a):
            if time.process_time() > deadline:
                return 1e6
            h = make_h2(a)
            s = h.sum()
            if s <= 0:
                return 1e6
            conv = fftconvolve(h, h)
            m = conv.max()
            if m <= 0:
                return 1e6
            L2 = (conv[:-1] ** 2 + conv[:-1] * conv[1:] + conv[1:] ** 2).sum() / 3.0
            # maximize R = L2/(s^2 * m) -> minimize -R
            return -L2 / (s * s * m)

        a0 = np.zeros(K - 1)
        try:
            res = minimize(obj, a0, method='L-BFGS-B',
                           options={'maxiter': 150, 'ftol': 1e-15, 'gtol': 1e-13})
            h2 = make_h2(res.x)
            r2 = _R_fast(h2)
            if r2 > best_r:
                best_r = r2
                best_h = h2
        except Exception:
            pass

    print(f"best R = {best_r:.9f}, best gamma = {best_gamma:.4f}")
    return best_h

