        hs = np.asarray(start, dtype=float)
        if hs.size > 0 and hs.sum() > 0 and hs.size <= 50000:
            rs = _R_fast(hs)
            if rs > best_r:
                best_r = rs
                best_h = hs.copy()

    # Power-law family h_n = (n+c)^(-alpha), optionally with Chebyshev log-taper
    # in the last 10% of indices.
    taper_start = int(N * 0.9)
    x = np.linspace(-1.0, 1.0, N - taper_start)
    KT = 4
    Tt = np.empty((KT, N - taper_start))
    Tt[0] = np.ones_like(x)
    if KT > 1:
        Tt[1] = x
    for k in range(2, KT):
        Tt[k] = 2.0 * x * Tt[k - 1] - Tt[k - 2]

    def make_h(c, alpha, coeffs):
        h = (n + c) ** (-alpha)
        if coeffs is not None and np.any(coeffs != 0):
            logp = coeffs @ Tt
            logp = np.clip(logp, -50.0, 50.0)
