    print(f"polish (c,alpha) R = {best_v2:.9f}, c = {best_p2[0]:.5f}, alpha = {best_p2[1]:.5f}")

    # Joint polish with taper coefficients
    p_full = np.concatenate([best_p2, np.zeros(KT)])
    best_vfull = best_v2
    best_pfull = p_full.copy()
    if time.process_time() < deadline * 0.9:
        try:
            res = minimize(negR_full, p_full, method='Nelder-Mead',
                           options={'maxiter': 1500, 'xatol': 1e-8, 'fatol': 1e-12})
            if -res.fun > best_vfull:
                best_vfull = -res.fun
                best_pfull = res.x
        except Exception:
            pass
    print(f"polish full R = {best_vfull:.9f}, c = {best_pfull[0]:.5f}, alpha = {best_pfull[1]:.5f}")

    h_final = make_h(best_pfull[0], best_pfull[1], best_pfull[2:])
    r_final = _R_fast(h_final)
    if r_final > best_r:
        best_h = h_final
        best_r = r_final

    if best_h is None:
        best_h = _binom(N)

    print(f"best R = {best_r:.9f}")
    return best_h
